                    if ($el.hasClass('selected')) {
                        $select.val('');
                        $el.removeClass('selected');

                        if ($el.attr('type') == 'radio') {
                            setTimeout(function() {
                                $el.prop('checked', false);
                            }, 100);
                        }
                    } else {
                        $el.addClass('selected').siblings('.selected').removeClass('selected');
                        $select.val(value);

                        if ($el.attr('type') == 'radio') {
