						},'+=0.2');

						tl.to(start,1.2, {
						  morphSVG:{shape:end, shapeIndex:8},
						  ease:"elastic.out(1, 0.75)"
						});

						tl.from(icon,1.2, {
						  x:'12px',
						  ease:"elastic.out(1, 0.75)"
						},'-=1.2');

						tl.add("open");

						tl.to(start,0.6, {
						  morphSVG:{shape:start},
						  ease:"elastic.out(1, 1.75)"
						},'+=0.2');

						tl.to(box,0.1, {
						  opacity:0,
						  ease:"sine.in"
					  	},'-=0.45');

						tl.to(box,0, {
						  visibility:'hidden', immediateRender:false
						});

						tl.add("close");

						tl.to(start,0.1, {
						  morphSVG:{shape:start}, immediateRender:false
						});

						tl.to(box,0.1, {
						  opacity:0, immediateRender:false
						});

						tl.to(box,0, {
						  visibility:'hidden', immediateRender:false
						});

						tl.add("hide");

						toggle.on('click',function(e){

							box.removeClass('hide');

							toggle.addClass('active');

							input.val('');

							if (isOpen==false) {

								tl.progress(0);
								tl.tweenTo("open");

								setTimeout(function(){
									input.focus();
								},700);

								isOpen=true;

							}

						});

						close.on('click',function(e){

							toggle.removeClass('active');

							if (close.hasClass('hide')) {

								box.addClass('hide');

								e.preventDefault();
								input.val('');

								tl.seek("close");
								tl.play();

								close.removeClass('hide');

								isOpen=false;

							} else {

								if (!input.val()) {
									tl.tweenTo("close");
									isOpen=false;
								}
							}

						});

						$this.find('#searchsubmit').on('click',function(e){
							if (!input.val()) {
								e.preventDefault();
								input.val('');
								tl.tweenTo("close");
							}
						});

					});

				})(jQuery);

