			function animateBoxBack(box){

				var $this  = jQuery(box),
					width  = $this.width(),
					height = $this.height(),
					ratio  = Math.round(100*(height/width)),
					svg    = $this.find('.box-back'),
					path   = svg.find('path');

				// get svg viewBox
				var viewBox = box.querySelector('.box-back').getAttribute('viewBox');

				var viewBoxValues = viewBox.split(' ');

				viewBoxValues  = viewBoxValues.splice(2, 2);

				var replace = viewBoxValues[1];

				var start    = path.attr('d'),
					startC   = path.attr('data-dclone'),
					end      = path.attr('data-end'),
					original = path.attr('data-original');

				start  = start.replace(new RegExp((replace-10),"g"),(ratio-10));
				start  = start.replace(new RegExp(replace,"g"),ratio);
				startC = startC.replace(new RegExp((replace-10),"g"),(ratio-10));
				startC = startC.replace(new RegExp(replace,"g"),ratio);
				end    = end.replace(new RegExp(replace,"g"),ratio);

				if (typeof(original) != 'undefined') {
					original = original.replace(new RegExp(replace,"g"),ratio);
				}

				box.querySelector('.box-back').setAttribute('viewBox','0 0 100 '+ratio);

				path.attr('d',start);
				path.attr('data-end',end);
				path.attr('data-dclone',startC);

				if (typeof(original) != 'undefined') {
					path.attr('data-original',original);
				}

			}

			function buildAnimateBoxTimeline(tl,box,delay,animation,stagger,content){

				var path = box.find('.box-back path');

				tl.from(box,0.2, {
				  opacity:0,
				},delay);

				switch(animation){
					case 'top':

						tl.from(box,1.2, {
							y:-100,
							scaleY:0,
							rotationZ:8,
							force3D:true,
							transformOrigin:'right top',
							ease:"elastic.out(1, 0.5)"
						},'-=0.1');

					break;

					case 'bottom':

						tl.from(box,1.2, {
							y:100,
							scaleY:0,
							rotationZ:8,
							force3D:true,
							transformOrigin:'right bottom',
							ease:"elastic.out(1, 0.5)"
						},'-=0.1');
					
					break;

					case 'left':

						tl.from(box,1.2, {
							x:-100,
							scaleX:0,
							rotationZ:-8,
							force3D:true,
							transformOrigin:'left center',
							ease:"elastic.out(1, 0.5)"
						},'-=0.1');
					
					break;

					case 'right':

						tl.from(box,1.2, {
							x:100,
							scaleX:0,
							rotationZ:8,
							force3D:true,
							transformOrigin:'right center',
							ease:"elastic.out(1, 0.5)"
						},'-=0.1');
					
					break;
				}


				tl.to(path,1.2, {
				  morphSVG:{shape:path.attr('data-end'), shapeIndex:8},
				  ease:"elastic.out"
				},'-=1');

				switch(stagger){

					case "left":

						tl.from(content,{
						  	duration: 0.8,
							x:-50,
							stagger: 0.05,
							opacity:0,
							ease:"expo.out"
						},'-=1.1');

					break;

					case "right":

						tl.from(content,{
						  	duration: 0.8,
							x:50,
							stagger: 0.05,
							opacity:0,
							ease:"expo.out"
						},'-=1.1');

					break;

					case "top":

						tl.from(content,{
						  	duration: 0.8,
							y:-50,
							stagger: 0.05,
							opacity:0,
							ease:"expo.out"
						},'-=1.1');

					break;

					case "bottom":

						tl.from(content,{
						  	duration: 0.8,
							y:50,
							stagger: 0.05,
							opacity:0,
							ease:"expo.out"
						},'-=1.1');

					break;
				}

				tl.add('end');

			}

			function buildStaggerBoxTimeline(tl,delay,interval,stagger,content){

				switch(stagger){

					case "left":

						tl.from(content,{
						  	duration: 0.8,
							x:-50,
							stagger: interval,
							opacity:0,
							ease:"expo.out"
						},delay);

					break;

					case "right":

						tl.from(content,{
						  	duration: 0.8,
							x:50,
							stagger: interval,
							opacity:0,
							ease:"expo.out"
						},delay);

					break;

					case "top":

						tl.from(content,{
						  	duration: 0.8,
							y:-50,
							stagger: interval,
							opacity:0,
							ease:"expo.out"
						},delay);

					break;

					case "bottom":

						tl.from(content,{
						  	duration: 0.8,
							y:50,
							stagger: interval,
							opacity:0,
							ease:"expo.out"
						},delay);

					break;
				}

			}

