		                $target.addClass('visible');
		            } else {
		                $target.removeClass('visible');
		            }

		        } else {
		            if ($value == null || $value == "" || $value == $placeholder) {
		                $target.addClass('visible');
		            } else {
		                $target.removeClass('visible');
		            }
		        }
		    };

			function etElements(){

				/* et-button
				----*/

					$('.et-button').each(function(){

						var $this  = $(this),
							effect = $this.data('effect');

						var tl = new gsap.timeline({paused: true});

						switch (effect) {
							case 'fill':

								var hover 	    = $this.find('span.hover'),
									icon        = $this.find('.icon svg'),
									color 	    = $this.data('color'),
									color_hover = $this.data('color-hover');

								tl.to(hover,0.6, {
								  scaleX:1,
								  transformOrigin:'left top',
								  ease:"power3.out"
							    });

								tl.to($this,0.1, {
								  css:{color:color_hover}
							    },'-=0.6');

								tl.to(icon,0.1, {
								  css:{fill:color_hover}
							    },'-=0.6');

								tl.add("in");

								tl.to(hover,0.6, {
								  scaleX:0,
								  transformOrigin:'right top',
								  ease:"power3.out"
							    });

								tl.to($this,0.1, {
								  css:{color:color}
							   },'-=0.6');

							   tl.to(icon,0.1, {
								 css:{fill:color}
							   },'-=0.6');

							   $this.hover(
									function(){
										tl.progress(0);
										tl.tweenTo("in");
									},
									function(){
										tl.play();
									}
								);

							break;

							case 'scale':

								var back = $this.find('.button-back .regular');

								$this.on('mouseover',function(){
									gsap.to(back,0.8, {
										scale:1.05,
										ease:"elastic.out"
									});
								});

								$this.on('mouseout',function(){
									gsap.to(back,0.8, {
										scale:1,
										ease:"expo.out"
									});
								});

							break;

							case 'move':

								$this.on('mousemove',function(e){

									var sxPos =  e.pageX - ($this.width()/2  + $this.offset().left);
									var syPos =  e.pageY - ($this.height()/2 + $this.offset().top);

									gsap.to( $this, 0.4, { 
										x: Math.round(0.1 * sxPos), 
										y: Math.round(0.5 * syPos), 
									});

								});

								$this.on('mouseleave',function(){
									gsap.to( $this, 0.4, { 
										x: 0, 
										y: 0, 
									});
								});

							break;
							
						}

						if ($this.hasClass('click-smooth') && $this.hasClass('modal-false')) {
							$this.unbind('click').on('click',function(){
								gsap.to(window, {
									duration: 1, 
									scrollTo: {y:$this.attr('href')},
									ease:Power3.easeOut 
								});
								return false;
							});
						}

						if (!$this.hasClass('click-smooth') && $this.hasClass('modal-true')) {
							$this.unbind('click').on('click',function(e){
								e.preventDefault();
								gsapLightbox($(this),false);
							});
						}

					});

					$('.et-header-button.submenu-toggle-click').each(function(){
						if ($(this).find('.sub-menu').length) {
							$(this).children('.et-button').removeClass('loading-menu');
						}
					});

					$('.et-header-button.submenu-toggle-hover').each(function(){

						if ($(this).find('.sub-menu').length) {
							$(this).children('.et-button').removeClass('loading-menu');
						}

						$(this).unbind('mouseenter').on('mouseenter',function(){
							if (!$(this).find('.sub-menu').length) {
								$(this).children('.et-button').addClass('loading-menu');
							} else {
								$(this).children('.et-button').removeClass('loading-menu');
							}
						});
					});

				/* et-icon
				----*/
			
					$('.click-true .hicon, .et-icon.click-true').each(function(){

						var $this  		  = $(this),
							iconBack   	  = $this.find('.icon-back path'),
							morphPath 	  = iconBack.data('hover'),
							morphOriginal = iconBack.attr('d'),
							shapeIndex    = 8;

						$this.unbind('mousedown').unbind('touchstart').on('mousedown touchstart',function(){
							gsap.to(iconBack,0.6, {
							  morphSVG:{shape: morphPath, shapeIndex: shapeIndex},
							  ease:'elastic.out'
							});
						});

						$this.unbind('mouseup').unbind('mouseleave').unbind('touchend').on('mouseup mouseleave touchend',function(){
							gsap.to(iconBack,0.6, {
								morphSVG:{shape: morphOriginal, shapeIndex: shapeIndex},
								ease:'elastic.out'
							});
						});

					});

				/* et-heading
				----*/

					$('.et-heading.animate-true').each(function(){

						var $this = $(this),
							delay = '+='+(0.2 + parseInt($this.data('delay'))/1000),
							text  = $this.find('.text');

						if(!$this.hasClass('fired')){

							if (!$this.hasClass('timeline')) {

								var tl = new gsap.timeline({paused: true});

								if ($this.hasClass('curtain')) {

									var curtain = $this.find('.curtain');

									tl.to(curtain,0.8, {
									  scaleX:1,
									  transformOrigin:'left top',
									  ease:"power3.out"
								    },delay);

								    tl.to(curtain,0.8, {
									  scaleX:0,
									  transformOrigin:'right top',
									  ease:"power3.out"
								    });

								    tl.to(text,0.2, {
									  opacity:1,
								    },'-=0.8');
								}

								else if ($this.hasClass('letter')) {
									var letterText = new SplitText($this.find('.text'),{type:"chars"});

									gsap.set($this,{perspective:500});

									tl.from(letterText.chars,{
										duration: 0.2,
									},delay);

									tl.from(letterText.chars,{
										duration: 0.6,
										opacity:0,
										scale:3,
										x:100,
										y:50,
										force3D:true,
										stagger: 0.01,
										ease:"expo.out"
									},'-=0.2');

								}

								else if ($this.hasClass('words')) {

									var wordsText = new SplitText($this.find('.text'),{type:"words"});
									
									gsap.set($this,{perspective:500});

									tl.from(wordsText.words,{
										duration: 0.2,
									},delay);

									tl.from(wordsText.words,{
										duration: 0.8,
										opacity:0,
										scaleY:1.5,
										transformOrigin:'left top',
										y:24,
										force3D:true,
										stagger: 0.04,
										ease:"expo.out"
									},'-=0.2');

								}

								else if ($this.hasClass('rows')) {
									
									var rowsText = new SplitText($this.find('.text'),{type:"lines"});
									
									gsap.set($this,{perspective:1000});

									tl.from(rowsText.lines,{
										duration: 0.4,
									},delay);

									tl.from(rowsText.lines,{
										duration: 1.2,
										opacity:0,
										rotationX:8,
										rotationY:-50,
										rotationZ:8,
										y:50,
										x:-50,
										z:50,
										transformOrigin:'left top',
										force3D:true,
										stagger: 0.08,
										ease:"expo.out"
									},'-=0.2');

								}

								$this.addClass('timeline');

								$this.waypoint({
					                handler: function(direction) {

					                	tl.progress(0);
										tl.play();

					                    this.destroy();

					                    $this.addClass('fired');

					                },
					                offset: 'bottom-in-view'
					            });

						}

						}

					});

				/* et-icon-list
				----*/
			
					$('.et-icon-list.animate-true').each(function(){

						var $this = $(this),
							delay = '+='+(0.2 + parseInt($this.data('delay'))/1000);

						if(!$this.hasClass('fired')){

							var tl = new gsap.timeline({paused: true});

							tl.to($this.find('li'),{
								duration: 0.8,
								x:0,
								opacity:1,
								stagger: 0.1,
								ease:"expo.out"
							},delay);

							$this.waypoint({
				                handler: function(direction) {

				                	tl.progress(0);
									tl.play();

				                    this.destroy();

				                    $this.addClass('fired');

				                },
				                offset: 'bottom-in-view'
				            });

						}

					});
			
				/* et-accordion
				----*/
			
					$('.et-accordion').each(function(){

						var $this = $(this);

						gsap.set($this.find('.toggle-title.active').next(),{
							opacity: 1,
		    				height: 'auto'
						});

						$this.find('.toggle-content-group').on('click', function(){
							if (!$(this).hasClass('active')) {
								$(this).find('.toggle-title').trigger('click');
							}
						});

						$this.find('.toggle-title').unbind('click').on('click', function(e){

							e.stopPropagation();

							var $self = $(this);

								if(!$self.hasClass('active')){
									if($this.hasClass('collapsible-true')){

										$self.addClass("active");
										$self.parent().siblings().find('.active').removeClass("active");
										$self.parent().addClass("active").siblings().removeClass("active");

										gsap.to($self.next(),0.6, {
											height:'auto',
											ease:"expo.out"
									  	});

									  	gsap.to($self.next(),0.2, {
											opacity:1,
									  	});

									  	gsap.to($this.find('.toggle-content').not($self.next()),0.1, {
											opacity:0,
									  	});

										gsap.to($this.find('.toggle-content').not($self.next()),0.6, {
											height:0,
											ease:"expo.out"
									  	});

									} else {
										$self.addClass("active");
										$self.parent().addClass("active");

										gsap.to($self.next(),0.6, {
											height:'auto',
											ease:"expo.out"
									  	});

									  	gsap.to($self.next(),0.2, {
											opacity:1,
									  	});

									}
								} else {
									if(!$this.hasClass('collapsible-true')){
										$self.removeClass("active");
										$self.parent().removeClass("active");

										gsap.to($self.next(),0.1, {
