				                },2000);

				                return;
				            }

				            var emailValue = email.val();
				            var n = emailValue.indexOf("@");
				            var r = emailValue.lastIndexOf(".");
				            if (n < 1 || r < n + 2 || r + 2 >= emailValue.length) {
				                valid =  "invalid";
				            } else {
				                valid = "valid";
				            }

				            validateValue(email.val(), email.next(".alert"), email.attr('data-placeholder'), true, valid);

