				                    $this.find(".et-mailchimp-error").addClass('visible');
				                    setTimeout(function(){
				                        $this.find(".et-mailchimp-error").removeClass('visible');
				                    },2000);
				                })
				                .always(function(){
				                    setTimeout(function(){
