				                        $this.find("input[name='fname']").val(fname.attr('data-placeholder'));
				                        $this.find("input[name='lname']").val(lname.attr('data-placeholder'));
				                        $this.find("input[name='phone']").val(phone.attr('data-placeholder'));
				                    },2000);
